import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Building using Containers","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-dev-guide/getting_started/container.md","filePath":"en/qgc-dev-guide/getting_started/container.md"}`),a={name:`en/qgc-dev-guide/getting_started/container.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="building-using-containers" tabindex="-1">Building using Containers <a class="header-anchor" href="#building-using-containers" aria-label="Permalink to “Building using Containers”">​</a></h1><p>QGroundControl provides Docker images that make it much easier to build a Linux-based QGC application, without installing Qt or any other requirements on your machine. The same images are used by CI, so a container build is also a quick way to reproduce a CI failure.</p><h2 id="about-the-container" tabindex="-1">About the Container <a class="header-anchor" href="#about-the-container" aria-label="Permalink to “About the Container”">​</a></h2><p>The container files are located in the <a href="https://github.com/mavlink/qgroundcontrol/tree/master/deploy/docker" target="_blank" rel="noreferrer"><code>deploy/docker</code></a> directory:</p><ul><li><code>Dockerfile</code>: a single multi-stage file with a target for each builder image: <code>linux</code> (x86_64 AppImage), <code>linux-cross</code> (aarch64 cross-build), <code>android</code> (APK) and <code>devcontainer</code> (see <a href="#vs-code-dev-container">VS Code Dev Container</a>).</li><li><code>variants.json</code>: the build variants, which select a target, base image and build arguments. The default <code>ubuntu</code> variant is based on <strong>Ubuntu 24.04</strong>; there are also <code>ubuntu-2204</code>, <code>ubuntu-2604</code>, <code>debian</code>, <code>fedora</code>, <code>arch</code>, <code>aarch64</code> and <code>android</code> variants.</li><li><code>run_docker.py</code>: builds a variant&#39;s image and runs a QGC build in it.</li></ul><p>Each image installs the dependencies and Qt at image build time with the scripts in <code>tools/setup</code>, using the versions from <code>.github/build-config.json</code>. Base images are pulled from the <a href="https://gallery.ecr.aws/docker" target="_blank" rel="noreferrer">Amazon ECR Public mirror</a> of the Docker official images, so builds aren&#39;t subject to Docker Hub&#39;s anonymous pull limit.</p><h2 id="building-qgc-using-the-script" tabindex="-1">Building QGC using the Script <a class="header-anchor" href="#building-qgc-using-the-script" aria-label="Permalink to “Building QGC using the Script”">​</a></h2><p>To build the image and then build QGC in it, run this command from the QGC root directory:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/run_docker.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span></span></code></pre></div><p>(<code>just docker</code> runs the same command.) Replace <code>ubuntu</code> with any variant from <code>variants.json</code>, and optionally append a build type (<code>Release</code> by default, or <code>Debug</code>, <code>RelWithDebInfo</code>, <code>MinSizeRel</code>). The build output, including the AppImage, is written to <code>build/</code> (<code>build-aarch64/</code> for the <code>aarch64</code> variant).</p><p>To rebuild with an image you already built, use <code>run</code>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/run_docker.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qgc-ubuntu-docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fuse</span></span></code></pre></div><p>The script runs the container as your user and mounts the source and build directories. <code>--fuse</code> gives the container access to FUSE, which the AppImage checks need. Environment variables adjust the run:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>BUILD_DIR</code></td><td>Build output directory (default: <code>build</code> in the source)</td></tr><tr><td><code>SOURCE_DIR</code></td><td>Source directory for <code>run</code> (default: the current directory)</td></tr><tr><td><code>JOBS</code></td><td>Number of parallel build jobs</td></tr><tr><td><code>CLEAN_BUILD</code></td><td><code>1</code> empties the build directory first (<code>aarch64</code> variant)</td></tr></tbody></table><p>Depending on your system resources, or the resources assigned to your Docker Daemon, the build step can take some time.</p><h2 id="building-manually" tabindex="-1">Building Manually <a class="header-anchor" href="#building-manually" aria-label="Permalink to “Building Manually”">​</a></h2><p>If you want to build using the container manually, first build the image by running the following command from the root of the QGC source code directory:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./deploy/docker/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qgc-ubuntu-docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The <code>-t</code> flag is essential. Keep in mind this is tagging the image for later reference since you can have multiple builds of the same container.</p></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The <code>linux</code> image builds x86_64 binaries. On a computer with an Apple silicon (ARM) chip you must also specify the build option <code>--platform linux/x86_64</code> as shown:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux/x86_64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./deploy/docker/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qgc-ubuntu-docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Otherwise you will get a build error like:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-x86_64:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Could</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> not</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/lib64/ld-linux-x86-64.so.2&#39;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> No</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> such</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> or</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> directory</span></span></code></pre></div></div><p>Then create a <code>build</code> directory in the source tree to hold the artifacts, and run the image using the tag provided above, from the root directory:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${PWD}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/project/source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${PWD}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/build:/project/build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qgc-ubuntu-docker</span></span></code></pre></div><p>On a Windows host, reference the current directory with <code>%cd%</code> instead:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %cd%:/project/source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %cd%/build:/project/build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qgc-ubuntu-docker</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>These commands run the build as <code>root</code> and without FUSE, so the AppImage checks are skipped. See <a href="https://github.com/mavlink/qgroundcontrol/blob/master/deploy/docker/run_docker.py" target="_blank" rel="noreferrer"><code>run_docker.py</code></a> for the exact <code>docker run</code> options the script uses.</p></div><h2 id="vs-code-dev-container" tabindex="-1">VS Code Dev Container <a class="header-anchor" href="#vs-code-dev-container" aria-label="Permalink to “VS Code Dev Container”">​</a></h2><p><a href="https://github.com/mavlink/qgroundcontrol/blob/master/.devcontainer/devcontainer.json" target="_blank" rel="noreferrer"><code>.devcontainer/devcontainer.json</code></a> builds the <code>devcontainer</code> target: the <code>linux</code> image with Qt and all dependencies preinstalled, plus a non-root <code>vscode</code> user. Open the repository in VS Code with the <a href="https://code.visualstudio.com/docs/devcontainers/containers" target="_blank" rel="noreferrer">Dev Containers</a> extension installed and choose <strong>Reopen in Container</strong>. The container installs the C++, CMake, QML and Python extensions and the QGC workspace settings, tasks and launch configurations, so you can build, test and debug from VS Code.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="windows-bash-r-no-such-file-or-directory" tabindex="-1">Windows: &#39;bash\\r&#39;: No such file or directory <a class="header-anchor" href="#windows-bash-r-no-such-file-or-directory" aria-label="Permalink to “Windows: &#39;bash\\r&#39;: No such file or directory”">​</a></h3><p>This error indicates that a Linux script is being run with Windows line endings. The repository&#39;s <code>.gitattributes</code> checks out shell scripts with Linux line endings, so this usually means the working tree was created by an older checkout or converted by another tool.</p><p>Recreate the working tree so Git applies the line-ending rules again (this discards uncommitted changes):</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hard</span></span></code></pre></div>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};